import json
from docx import Document

def replace_in_container(container, placeholders):
    # Handle paragraphs in this container (could be doc, cell, header, etc.)
    if hasattr(container, 'paragraphs'):
        for p in container.paragraphs:
            for key, value in placeholders.items():
                placeholder = f"{{{{{key}}}}}"
                if placeholder in p.text:
                    # Try replacing in runs first to preserve formatting
                    found_in_run = False
                    for run in p.runs:
                        if placeholder in run.text:
                            run.text = run.text.replace(placeholder, str(value))
                            found_in_run = True

                    # If not found in a single run, fall back to paragraph.text
                    if not found_in_run:
                        # Note: this might lose some formatting
                        p.text = p.text.replace(placeholder, str(value))

    # Handle tables in this container
    if hasattr(container, 'tables'):
        for table in container.tables:
            for row in table.rows:
                for cell in row.cells:
                    # Recursively handle cells (which can contain paragraphs and nested tables)
                    replace_in_container(cell, placeholders)

def process_docx(template_path, output_path, data):
    doc = Document(template_path)
    placeholders = data.copy()

    # 1. Handle markers in main document paragraphs
    for p in doc.paragraphs:
        if "{{IF_RELOCATION}}" in p.text:
            p.text = p.text.replace("{{IF_RELOCATION}}", "")
        if "{{END_IF_RELOCATION}}" in p.text:
            p.text = p.text.replace("{{END_IF_RELOCATION}}", "")

    # 2. Replace in main document (paragraphs and tables)
    replace_in_container(doc, placeholders)

    # 3. Replace in headers and footers
    for section in doc.sections:
        replace_in_container(section.header, placeholders)
        replace_in_container(section.footer, placeholders)
        if hasattr(section, 'first_page_header') and section.first_page_header:
            replace_in_container(section.first_page_header, placeholders)
        if hasattr(section, 'first_page_footer') and section.first_page_footer:
            replace_in_container(section.first_page_footer, placeholders)
        if hasattr(section, 'even_page_header') and section.even_page_header:
            replace_in_container(section.even_page_header, placeholders)
        if hasattr(section, 'even_page_footer') and section.even_page_footer:
            replace_in_container(section.even_page_footer, placeholders)

    doc.save(output_path)

if __name__ == "__main__":
    with open("employee_data.json", "r") as f:
        data = json.load(f)
    process_docx("offer_letter_template.docx", "offer_letter_filled.docx", data)

